//! The crate against the reference implementation.
//!
//! `golden.json` was generated by the R implementation this crate was
//! distilled from, with every function run on fixed inputs (the selection
//! is deterministic given the uniforms). The crate must reproduce the
//! integer outputs exactly and the floating-point outputs to near machine
//! precision; a looser tolerance is a translation error, not rounding.

use chromy_core::*;
use serde_json::Value;

fn fixtures() -> Value {
    serde_json::from_str(include_str!("golden.json")).expect("golden.json parses")
}

fn f64s(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

fn close(a: f64, b: f64, tol: f64, what: &str) {
    let scale = 1.0_f64.max(a.abs()).max(b.abs());
    assert!(
        (a - b).abs() <= tol * scale,
        "{what}: {a} vs {b} (diff {})",
        (a - b).abs()
    );
}

fn all_close(a: &[f64], b: &[f64], tol: f64, what: &str) {
    assert_eq!(a.len(), b.len(), "{what}: lengths differ");
    for (i, (&x, &y)) in a.iter().zip(b).enumerate() {
        if x.is_nan() && y.is_nan() {
            continue;
        }
        close(x, y, tol, &format!("{what}[{i}]"));
    }
}

#[test]
fn pmr_matches_the_reference() {
    for case in fixtures()["pmr"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let lambda = f64s(&case["lambda"]);
        let unif = f64s(&case["unif"]);
        let priority = usizes(&case["priority"]);

        let got = pmr(&lambda, &unif, &priority).unwrap_or_else(|e| panic!("{name}: {e}"));

        let hits: Vec<u64> = case["hits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_u64().unwrap())
            .collect();
        assert_eq!(got.hits, hits, "{name}: hits");
        all_close(
            &got.effective_lambda,
            &f64s(&case["effective_lambda"]),
            1e-14,
            &format!("{name}: effective lambda"),
        );
        close(
            got.eps_sum,
            case["eps_sum"].as_f64().unwrap(),
            1e-14,
            &format!("{name}: eps sum"),
        );
        let corrected = case["corrected_unit"].as_u64().map(|x| x as usize);
        assert_eq!(got.corrected_unit, corrected, "{name}: corrected unit");
        assert_eq!(
            got.adjusted_crossings,
            case["adjusted_crossings"].as_u64().unwrap() as usize,
            "{name}: adjusted crossings"
        );
    }
}

#[test]
fn serpentine_matches_the_reference() {
    for case in fixtures()["serpentine"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let mut numeric: Vec<Vec<f64>> = Vec::new();
        let mut categorical: Vec<Vec<String>> = Vec::new();
        let mut shape: Vec<(bool, usize)> = Vec::new(); // (is_numeric, index)
        for key in case["keys"].as_array().unwrap() {
            if key["kind"] == "num" {
                shape.push((true, numeric.len()));
                numeric.push(f64s(&key["values"]));
            } else {
                shape.push((false, categorical.len()));
                categorical.push(
                    key["values"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|v| v.as_str().unwrap().to_string())
                        .collect(),
                );
            }
        }
        let keys: Vec<Key> = shape
            .iter()
            .map(|&(is_num, i)| {
                if is_num {
                    Key::Numeric(&numeric[i])
                } else {
                    Key::Categorical(&categorical[i])
                }
            })
            .collect();

        let got = match case["sort"].as_str().unwrap() {
            "SERP" => serpentine(&keys),
            "NEST" => nested(&keys),
            other => panic!("unknown sort {other}"),
        }
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(got, usizes(&case["order"]), "{name}: order");
    }
}

#[test]
fn expected_hits_match_the_reference() {
    for case in fixtures()["lambda"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let got = expected_hits(
            &f64s(&case["size"]),
            case["n"].as_u64().unwrap(),
            case["min_replacement"].as_bool().unwrap(),
        )
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        all_close(&got, &f64s(&case["lambda"]), 1e-14, name);
    }
}

#[test]
fn mpps_matches_the_reference() {
    for case in fixtures()["mpps"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let got = mpps(
            &f64s(&case["x"]),
            case["nrow"].as_u64().unwrap() as usize,
            &f64s(&case["n_j"]),
        )
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        all_close(&got, &f64s(&case["size"]), 1e-14, name);
    }
}

#[test]
fn eqcv_matches_the_reference() {
    for case in fixtures()["eqcv"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let got = eqcv(
            &f64s(&case["x"]),
            case["nrow"].as_u64().unwrap() as usize,
            case["n"].as_u64().unwrap(),
            EqcvOptions::default(),
        )
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        // The search iterates; the last few bits may differ in the final
        // normalisation, so the tolerance is loose only relative to the
        // others.
        all_close(&got.n_j, &f64s(&case["n_j"]), 1e-9, name);
        assert!(got.converged, "{name}: should converge");
    }
}

#[test]
fn the_estimator_matches_the_reference() {
    for case in fixtures()["estimator"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let hits: Vec<u64> = case["hits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_u64().unwrap())
            .collect();
        let got = multiplicity_estimate(
            &f64s(&case["y"]),
            case["nrow"].as_u64().unwrap() as usize,
            &usizes(&case["units"]),
            &usizes(&case["positions"]),
            &f64s(&case["expected_hits"]),
            &hits,
        )
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        all_close(
            &got.total,
            &f64s(&case["ht"]),
            1e-12,
            &format!("{name}: total"),
        );
        assert_eq!(
            got.random_draws,
            case["m"].as_u64().unwrap() as usize,
            "{name}: random draws"
        );
        let se: Vec<f64> = got.sd_variance.iter().map(|v| v.sqrt()).collect();
        all_close(&se, &f64s(&case["se_sd"]), 1e-12, &format!("{name}: SE"));
    }
}
